	protected void waitForDecompiler()
	{
		waitForSwing();
		waitForCondition(() => !provider.isBusy());
		waitForSwing();
	}

	protected void setDecompilerLocation(int line, int charPosition)
	{
		DecompilerPanel panel = provider.getDecompilerPanel();
		FieldLocation loc = this.loc(line, charPosition);
		panel.setCursorPosition(loc);

		ClangTextField? field = (loc.row >= 0 && loc.row < panel.getFields().Count) ? (ClangTextField)panel.getFields()[loc.row] : null;
		if (field != null)
		{
			panel.getHighlightController().fieldLocationChanged(loc, field, EventTrigger.GUI_ACTION);
			ClangToken? tok = field.getToken(loc);
			if (tok is ClangVariableToken)
			{
				codeBrowser.goTo(new VariableLocFieldLocation(program, provider.getController().getFunction().getEntryPoint(), null, 0, loc.row, loc.col));
			}
			else if (tok is ClangFuncNameToken && loc.row == 3 && tok.getText() == "FUN_010059a3")
			{
				codeBrowser.goTo(new FunctionNameFieldLocation(program, provider.getController().getFunction().getEntryPoint()));
			}
			else if (tok != null && tok.getMinAddress() != null)
			{
				codeBrowser.goTo(new ProgramLocation(program, tok.getMinAddress()));
			}
		}

		waitForSwing();
	}

