		return (ClangTextField)fields.get(lineIndex);
	}

	protected ClangToken getToken(int line, int col) => getToken(loc(line, col));
	protected ClangToken getToken(FieldLocation loc) => getToken(provider, loc);

	protected ClangToken getToken(DecompilerProvider theProvider, FieldLocation loc)
	{
		int lineNumber = loc.getIndex().intValue() + 1;
		ClangTextField field = getFieldForLine(theProvider, lineNumber);
		return field.getToken(loc);
	}

	protected DecompilerPanel getDecompilerPanel() => provider.getDecompilerPanel();

	protected ClangToken getToken()
	{
		waitForDecompiler();
		return getToken(provider);
	}

	protected ClangToken getCursorToken() => getToken(provider);

	protected ClangToken getToken(DecompilerProvider theProvider)
	{
		DecompilerPanel panel = theProvider.getDecompilerPanel();
		FieldLocation loc = panel.getCursorPosition();
		return getToken(theProvider, loc);
	}

	protected string getTokenText(FieldLocation loc) => getToken(loc).getText();

	protected void assertToken(string tokenText, int line, params int[] cols)
	{
		foreach (int col in cols)
		{
			ClangToken token = getToken(line, col);
			string text = token.getText();
			assertEquals(tokenText, text);
		}
	}

	protected ClangTextField? getLineStarting(string val)
	{
		DecompilerPanel panel = provider.getDecompilerPanel();
		foreach (Field field in panel.getFields())
		{
			if (field is ClangTextField textField && textField.getText().Trim().StartsWith(val))
			{
				return textField;
			}
		}
		return null;
	}

	protected ClangTextField? getLineContaining(string val)
	{
		DecompilerPanel panel = provider.getDecompilerPanel();
		foreach (Field field in panel.getFields())
		{
			if (field is ClangTextField textField && textField.getText().Contains(val))
			{
				return textField;
			}
		}
		return null;
	}

	protected HighFunction getHighFunction() => provider.getController().getHighFunction();
	protected Function getCurrentFunction() => provider.getController().getFunction();
