public class ActionAdapter : DockingAction
{
	private readonly Action<ActionContext> action;
	public ActionAdapter(string name, string owner, Action<ActionContext> action) : base(name, owner)
	{
		this.action = action;
	}
	public override void actionPerformed(ActionContext context) => action(context);
}

